import{_ as p,a0 as d,w as o,s as r,I as a,x as n,a1 as t,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在 Linux 中自動配置 IPv6 地址 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中自動配置 IPv6 地址 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中自動配置 IPv6 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中自動配置 IPv6 地址 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171214 IPv6 Auto-Configuration in Linux","title":"在 Linux 中自動配置 IPv6 地址","tag":"201803","desc":""},"relativePath":"201803/20171214 IPv6 Auto-Configuration in Linux.md","filePath":"[post].md"}'),u={name:"201803/20171214 IPv6 Auto-Configuration in Linux.md"};function g(v,s,f,b,k,c){const i=d("Link");return o(),r("div",null,[s[30]||(s[30]=a("h1",{id:"在-linux-中自動配置-ipv6-地址",tabindex:"-1"},[n("在 Linux 中自動配置 IPv6 地址 "),a("a",{class:"header-anchor",href:"#在-linux-中自動配置-ipv6-地址","aria-label":"Permalink to “在 Linux 中自動配置 IPv6 地址”"},"​")],-1)),s[31]||(s[31]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_5.png?itok=3kN83IjL",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("在 ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-1"},{default:e(()=>[...s[0]||(s[0]=[n("KVM 中測試 IPv6 網絡：第 1 部分",-1)])]),_:1}),s[2]||(s[2]=n(" 一文中，我們學習了關於",-1)),s[3]||(s[3]=a("ruby",null,[n("唯一本地地址"),a("rt",null,"unique local addresses")],-1)),s[4]||(s[4]=n("（ULA）的相關內容。在本文中，我們將學習如何為 ULA 自動配置 IP 地址。",-1))]),s[32]||(s[32]=l(`<h3 id="何時使用唯一本地地址" tabindex="-1">何時使用唯一本地地址 <a class="header-anchor" href="#何時使用唯一本地地址" aria-label="Permalink to “何時使用唯一本地地址”">​</a></h3><p><ruby>唯一本地地址<rt>unique local addresses</rt></ruby>（ULA）使用 <code>fd00::/8</code> 地址塊，它類似於我們常用的 IPv4 的私有地址：<code>10.0.0.0/8</code>、<code>172.16.0.0/12</code>、以及 <code>192.168.0.0/16</code>。但它們並不能直接替換。IPv4 的私有地址分類和網絡地址轉換（NAT）功能是為了緩解 IPv4 地址短缺的問題，這是個明智的解決方案，它延緩了本該被替換的 IPv4 的生命週期。IPv6 也支持 NAT，但是我想不出使用它的理由。IPv6 的地址數量遠遠大於 IPv4；它是不一樣的，因此需要做不一樣的事情。</p><p>那麼，ULA 存在的意義是什麼呢？尤其是在我們已經有了<ruby>本地鏈路地址<rt>link-local addresses</rt></ruby>（<code>fe80::/10</code>）時，到底需不需要我們去配置它們呢？它們之間（LCTT 譯註：指的是唯一本地地址和本地鏈路地址）有兩個重要的區別。一是，本地鏈路地址是不可路由的，因此，你不能跨子網使用它。二是，ULA 是你自己管理的；你可以自己選擇它用於子網的地址範圍，並且它們是可路由的。</p><p>使用 ULA 的另一個好處是，如果你只是在局域網中“混日子”的話，你不需要為它們分配全局單播 IPv6 地址。當然了，如果你的 ISP 已經為你分配了 IPv6 的<ruby>全局單播地址<rt>global unicast addresses</rt></ruby>，就不需要使用 ULA 了。你也可以在同一個網絡中混合使用全局單播地址和 ULA，但是，我想不出這樣使用的一個好理由，並且要一定確保你不使用網絡地址轉換（NAT）以使 ULA 可公共訪問。在我看來，這是很愚蠢的行為。</p><p>ULA 是僅為私有網絡使用的，並且應該阻止其流出你的網絡，不允許進入因特網。這很簡單，在你的邊界設備上只要阻止整個 <code>fd00::/8</code> 範圍的 IPv6 地址即可實現。</p><h3 id="地址自動配置" tabindex="-1">地址自動配置 <a class="header-anchor" href="#地址自動配置" aria-label="Permalink to “地址自動配置”">​</a></h3><p>ULA 不像本地鏈路地址那樣自動配置的，但是使用 radvd 設置自動配置是非常容易的，radva 是路由器公告守護程序。在你開始之前，運行 <code>ifconfig</code> 或者 <code>ip addr show</code> 去查看你現有的 IP 地址。</p><p>在生產系統上使用時，你應該將 radvd 安裝在一台單獨的路由器上，如果只是測試使用，你可以將它安裝在你的網絡中的任意 Linux PC 上。在我的小型 KVM 測試實驗室中，我使用 <code>apt-get install radvd</code> 命令把它安裝在 Ubuntu 上。安裝完成之後，我先不啓動它，因為它還沒有配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status radvd</span></span>
<span class="line"><span>● radvd.service - LSB: Router Advertising Daemon</span></span>
<span class="line"><span>   Loaded: loaded (/etc/init.d/radvd; bad; vendor preset: enabled)</span></span>
<span class="line"><span>   Active: active (exited) since Mon 2017-12-11 20:08:25 PST; 4min 59s ago</span></span>
<span class="line"><span>     Docs: man:systemd-sysv-generator(8)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 systemd[1]: Starting LSB: Router Advertising Daemon...</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: Starting radvd:</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: * /etc/radvd.conf does not exist or is empty.</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: * See /usr/share/doc/radvd/README.Debian</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: * radvd will *not* be started.</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 systemd[1]: Started LSB: Router Advertising Daemon.</span></span></code></pre></div><p>這些所有的消息有點讓人困惑，實際上 radvd 並沒有運行，你可以使用經典命令 <code>ps | grep radvd</code> 來驗證這一點。因此，我們現在需要去創建 <code>/etc/radvd.conf</code> 文件。拷貝這個示例，將第一行的網絡接口名替換成你自己的接口名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>interface ens7 {</span></span>
<span class="line"><span>  AdvSendAdvert on;</span></span>
<span class="line"><span>  MinRtrAdvInterval 3;</span></span>
<span class="line"><span>  MaxRtrAdvInterval 10;</span></span>
<span class="line"><span>  prefix fd7d:844d:3e17:f3ae::/64</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>                AdvOnLink on;</span></span>
<span class="line"><span>                AdvAutonomous on;</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>};</span></span></code></pre></div>`,11)),a("p",null,[s[6]||(s[6]=n("前綴（",-1)),s[7]||(s[7]=a("code",null,"prefix",-1)),s[8]||(s[8]=n("）定義了你的網絡地址，它是地址的前 64 位。前兩個字符必須是 ",-1)),s[9]||(s[9]=a("code",null,"fd",-1)),s[10]||(s[10]=n("，前綴接下來的剩餘部分你自己定義它，最後的 64 位留空，因為 radvd 將去分配最後的 64 位。前綴後面的 16 位用來定義子網，剩餘的地址定義為主機地址。你的子網必須總是 ",-1)),s[11]||(s[11]=a("code",null,"/64",-1)),s[12]||(s[12]=n("。RFC 4193 要求地址必須隨機生成；查看 ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-1"},{default:e(()=>[...s[5]||(s[5]=[n("在 KVM 中測試 IPv6 Networking：第 1 部分",-1)])]),_:1}),s[13]||(s[13]=n(" 學習創建和管理 ULAs 的更多知識。",-1))]),s[33]||(s[33]=l(`<h3 id="ipv6-轉發" tabindex="-1">IPv6 轉發 <a class="header-anchor" href="#ipv6-轉發" aria-label="Permalink to “IPv6 轉發”">​</a></h3><p>IPv6 轉發必須要啓用。下面的命令去啓用它，重啓後生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysctl -w net.ipv6.conf.all.forwarding=1</span></span></code></pre></div><p>取消註釋或者添加如下的行到 <code>/etc/sysctl.conf</code> 文件中，以使它永久生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>net.ipv6.conf.all.forwarding = 1</span></span></code></pre></div><p>啓動 radvd 守護程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl stop radvd</span></span>
<span class="line"><span>$ sudo systemctl start radvd</span></span></code></pre></div><p>這個示例在我的 Ubuntu 測試系統中遇到了一個怪事；radvd 總是停止，我查看它的狀態卻沒有任何問題，做任何改變之後都需要重新啓動 radvd。</p><p>啓動成功後沒有任何輸出，並且失敗也是如此，因此，需要運行 <code>sudo systemctl status radvd</code> 去查看它的運行狀態。如果有錯誤，<code>systemctl</code> 會告訴你。一般常見的錯誤都是 <code>/etc/radvd.conf</code> 中的語法錯誤。</p><p>在 Twitter 上抱怨了上述問題之後，我學到了一件很酷的技巧：當你運行 <code> journalctl -xe --no-pager</code> 去調試 <code>systemctl</code> 錯誤時，你的輸出會被換行，然後，你就可以看到錯誤信息。</p><p>現在檢查你的主機，查看它們自動分配的新地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig</span></span>
<span class="line"><span>ens7      Link encap:Ethernet  HWaddr 52:54:00:57:71:50  </span></span>
<span class="line"><span>          [...]</span></span>
<span class="line"><span>          inet6 addr: fd7d:844d:3e17:f3ae:9808:98d5:bea9:14d9/64 Scope:Global</span></span>
<span class="line"><span>          [...]</span></span></code></pre></div><p>本文到此為止，下週繼續學習如何為 ULA 管理 DNS，這樣你就可以使用一個合適的主機名來代替這些長長的 IPv6 地址。</p>`,13)),a("p",null,[s[15]||(s[15]=n("通過來自 Linux 基金會和 edX 的 ",-1)),t(i,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:e(()=>[...s[14]||(s[14]=[n("“Linux 入門”",-1)])]),_:1}),s[16]||(s[16]=n(" 免費課程學習更多 Linux 的知識。",-1))]),s[34]||(s[34]=a("hr",null,null,-1)),a("p",null,[s[18]||(s[18]=n("via: ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/12/ipv6-auto-configuration-linux"},{default:e(()=>[...s[17]||(s[17]=[n("https://www.linux.com/learn/intro-to-linux/2017/12/ipv6-auto-configuration-linux",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=n("作者：",-1)),t(i,{href:"https://www.linux.com/users/cschroder"},{default:e(()=>[...s[19]||(s[19]=[n("Carla Schroder",-1)])]),_:1}),s[23]||(s[23]=n(" 譯者：",-1)),t(i,{href:"https://github.com/qhwdw"},{default:e(()=>[...s[20]||(s[20]=[n("qhwdw",-1)])]),_:1}),s[24]||(s[24]=n(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[21]||(s[21]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[26]||(s[26]=[n("Linux中國",-1)])]),_:1}),s[29]||(s[29]=n(" 榮譽推出",-1))])])}const L=p(u,[["render",g]]);export{h as __pageData,L as default};
